-- Export views: one tidy table per record type, plus stratigraphic relationships.
-- GENERATED by tools/make-views.mjs from js/schema.js. Don't edit by hand.
-- Paste into Supabase > SQL Editor and Run (after schema.sql).
-- Deleted records are left out. Every view has a geom column (EPSG:27700) for QGIS / ArcGIS Pro.

drop view if exists public.fw_contexts;
create view public.fw_contexts with (security_invoker = true) as
select
  r.id,
  p.site_code,
  r.number as number,
  nullif(r.data ->> 'contextType', '') as context_type,
  nullif(r.data ->> 'trench', '') as trench,
  nullif(r.data ->> 'feature', '') as feature,
  nullif(r.data ->> 'intervention', '') as intervention,
  nullif(r.data ->> 'colour', '') as colour,
  nullif(r.data ->> 'composition', '') as composition,
  nullif(r.data ->> 'compaction', '') as compaction,
  nullif(r.data ->> 'inclusions', '') as inclusions,
  nullif(r.data ->> 'shapePlan', '') as shape_plan,
  nullif(r.data ->> 'sides', '') as sides,
  nullif(r.data ->> 'base', '') as base_shape,
  nullif(r.data ->> 'breakTop', '') as break_top,
  nullif(r.data ->> 'breakBase', '') as break_base,
  nullif(r.data ->> 'orientation', '') as orientation,
  nullif(r.data ->> 'materials', '') as materials,
  nullif(r.data ->> 'bond', '') as bond,
  nullif(r.data ->> 'bonding', '') as bonding,
  nullif(r.data ->> 'length', '')::numeric as length_m,
  nullif(r.data ->> 'width', '')::numeric as width,
  nullif(r.data ->> 'depth', '')::numeric as depth,
  nullif(r.data ->> 'levelTop', '')::numeric as level_top,
  nullif(r.data ->> 'levelBase', '')::numeric as level_base,
  nullif(r.data ->> 'description', '') as description,
  nullif(r.data ->> 'interpretation', '') as interpretation,
  nullif(r.data ->> 'excavationMethod', '') as excavation_method,
  coalesce((r.data ->> 'finds')::boolean, false) as finds,
  coalesce((r.data ->> 'samples')::boolean, false) as samples,
  nullif(r.data ->> 'datingEvidence', '') as dating_evidence,
  nullif(r.data ->> 'recorder', '') as recorder,
  nullif(r.data ->> 'date', '')::date as record_date,
  nullif(r.data ->> 'notes', '') as notes,
  (select string_agg((case x ->> 'rel' when 'above' then 'Above (later than)' when 'below' then 'Below (earlier than)' when 'cuts' then 'Cuts' when 'cutBy' then 'Cut by' when 'fills' then 'Fills' when 'filledBy' then 'Filled by' when 'abuts' then 'Abuts' when 'abuttedBy' then 'Abutted by' when 'sameAs' then 'Same as' else x ->> 'rel' end) || ' ' || (x ->> 'target'), '; ')
     from jsonb_array_elements(coalesce(r.data -> 'relationships', '[]'::jsonb)) x) as relationships,
  r.data -> 'location' ->> 'gridRef' as grid_ref,
  nullif(r.data -> 'location' ->> 'accuracy', '')::numeric as gps_accuracy_m,
  r.latitude,
  r.longitude,
  r.easting,
  r.northing,
  r.geom,
  r.updated_by,
  r.updated_at,
  r.synced_at
from public.fw_records r
join public.fw_projects p on p.id = r.project_id
where r.type = 'context' and not r.deleted and not p.deleted;
grant select on public.fw_contexts to authenticated;

