drop view if exists public.fw_finds;
create view public.fw_finds with (security_invoker = true) as
select
  r.id,
  p.site_code,
  'SF' || r.number as number,
  nullif(r.data ->> 'context', '') as context,
  nullif(r.data ->> 'material', '') as material,
  nullif(r.data ->> 'objectType', '') as object_type,
  nullif(r.data ->> 'count', '')::numeric as count,
  nullif(r.data ->> 'period', '') as period,
  nullif(r.data ->> 'levelZ', '')::numeric as level_z,
  coalesce((r.data ->> 'bagged')::boolean, false) as bagged,
  nullif(r.data ->> 'description', '') as description,
  nullif(r.data ->> 'recorder', '') as recorder,
  nullif(r.data ->> 'date', '')::date as record_date,
  r.data -> 'location' ->> 'gridRef' as grid_ref,
  nullif(r.data -> 'location' ->> 'accuracy', '')::numeric as gps_accuracy_m,
  r.latitude,
  r.longitude,
  r.easting,
  r.northing,
  r.geom,
  r.updated_by,
  r.updated_at,
  r.synced_at
from public.fw_records r
join public.fw_projects p on p.id = r.project_id
where r.type = 'find' and not r.deleted and not p.deleted;
grant select on public.fw_finds to authenticated;

